INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('70e0721e-e765-5c42-8192-d7875f875d1e','TEXT','The Tiny Ferry','Zoe liked helping at the river workshop, especially when there was a small job that nobody had planned. One Wednesday, Zoe noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
