INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('7dc40534-c313-59b5-bd47-dde42dc3aba2','TEXT','The Creek Sound Map — A Different Day','Kai liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Wednesday, Kai noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
