INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fd75fcad-3c48-5aa8-8969-f2290622978e','TEXT','The Creek Sound Map','Kai liked helping at the creek reserve, especially when there was a small job that nobody had planned. One Friday, Kai noticed the sound map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('59a1a911-961f-544e-85ca-31251a05be9b','TEXT','The Repaired Book — A Different Day','Mia liked helping at the library corner, especially when there was a small job that nobody had planned. One Saturday, Mia noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
