INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('fba03fc7-77eb-5cd9-9c07-060cac19b5fc','TEXT','The Repaired Book','Mia liked helping at the library corner, especially when there was a small job that nobody had planned. One Wednesday, Mia noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
