INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1d4f3fc9-761f-58af-bd68-a8fb71d84935','TEXT','The Seed Library','Noah liked helping at the community garden, especially when there was a small job that nobody had planned. One Wednesday, Noah noticed the seed envelopes was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
